//! 🧪️ Genuine native slots retain originals under foreign, underfunded and outstanding-reader refusals.
use super::*;

fn work(payload_bytes:usize)->usize{static POLICY:std::sync::OnceLock<(usize,usize)>=std::sync::OnceLock::new();let(per_byte,fixed)=*POLICY.get_or_init(||{let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();(usize::try_from(law["policy"]["stepsPerPayloadByte"].as_u64().unwrap()).unwrap(),usize::try_from(law["policy"]["fixedSteps"].as_u64().unwrap()).unwrap())});payload_bytes.checked_add(1).and_then(|bytes|bytes.checked_mul(per_byte)).and_then(|steps|steps.checked_add(fixed)).expect("original slot finite fixture work overflow")}
fn tick(remaining:&mut usize){*remaining=remaining.checked_sub(1).expect("original slot exhausted finite fixture work before terminal custody");}
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes+d.capacity_bytes<=4096);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
#[test]
fn original_slot_preserves_native_payload_and_waits_for_every_projected_reader(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();assert_eq!(law["policy"]["maximumItems"],1);assert_eq!(law["policy"]["owningProjection"],true);for row in law["workCases"].as_array().unwrap(){assert_eq!(work(usize::try_from(row["payloadBytes"].as_u64().unwrap()).unwrap()),usize::try_from(row["expectedSteps"].as_u64().unwrap()).unwrap());}
 let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default());
 let mut original=RetainedOriginalSlot::new("original α\0😀".repeat(8192));let mut remaining=work(original.get().len());let pointer=original.get().as_ptr();let key=original.key();let foreign=RetainedOriginalSlot::new(String::new()).key();assert!(original.demands(foreign).is_err());
 while original.borrow(key).is_err(){tick(&mut remaining);let d=original.demands(key).unwrap();for axis in 0..5{let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let(step,heap)=crate::observe_retirement_allocations(||original.advance_read(key,&factory,denied).result.unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));assert_eq!(original.get().as_ptr(),pointer);}
  let(step,heap)=crate::observe_retirement_allocations(||original.advance_read(key,&factory,grant(d)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
 let projection=semio_framework_value_retained_clone::RetainedOwnedProjection::<String>::constructor_demand();let identity=original.borrow(key).unwrap().source_identity();for(candidate,g)in[(foreign,grant(projection)),(key,RetainedCloneGrant{maximum_items:0,..grant(projection)}),(key,RetainedCloneGrant{maximum_depth:0,..grant(projection)})]{let(result,heap)=crate::observe_retirement_allocations(||original.retain_read(candidate,g));assert_eq!(result.work,0);assert!(result.result.is_err());assert_eq!(heap,(0,0));assert_eq!(original.borrow(key).unwrap().source_identity(),identity);assert_eq!(original.get().as_ptr(),pointer);}let((mut lease,progress),heap)=crate::observe_retirement_allocations(||original.retain_read(key,grant(projection)).result.unwrap());assert!(progress.fits(grant(projection)));assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));assert!(lease.matches_source(original.borrow(key).unwrap()));assert_eq!(lease.borrow().unwrap().get().as_ptr(),pointer);
 let mut withdrawn=None;let(refused,heap)=crate::observe_retirement_allocations(||original.take_original(key,&mut withdrawn,grant(RetainedOriginalSlot::<String>::transfer_demand())));assert!(refused.is_err());assert!(withdrawn.is_none());assert_eq!(heap,(0,0));
 let mut next=Some("next".to_string());let next_error=original.replace(&mut next,grant(RetainedOriginalSlot::<String>::replace_demand())).unwrap_err();assert_eq!(next_error.kind,ValueRefusalKind::InvariantViolated);assert_eq!(next.as_deref(),Some("next"));assert_eq!(original.get().as_ptr(),pointer);let mut returned=None;
 for _ in 0..8{let d=original.return_demands(key,4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||original.return_read(key,&mut returned,grant(d)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(returned.is_none());assert_eq!(original.get().as_ptr(),pointer);}
 for _ in 0..10000{if lease.terminal_is_empty(){break;}let d=lease.close_demand(4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||lease.close_step(grant(d)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(lease.terminal_is_empty());
 for _ in 0..10000{if !original.has_read(){break;}let d=original.return_demands(key,4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||original.return_read(key,&mut returned,grant(d)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(!original.has_read());assert!(Arc::ptr_eq(returned.as_ref().unwrap(),&factory));assert_eq!(original.get().as_ptr(),pointer);
 let mut issuer=crate::FactoryAuthority::new(returned.take().unwrap());while !issuer.terminal_is_empty(){tick(&mut remaining);let d=issuer.demands(4096).unwrap();issuer.step(grant(d)).result.unwrap();}
 let value=original.try_into_original().unwrap_or_else(|_|panic!("returned original slot remains uniquely owned"));assert_eq!(value.as_ptr(),pointer);let mut close=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();while !close.terminal_is_empty(){tick(&mut remaining);let d=close.next_demand(4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||close.step(grant(d)).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
}
#[test]
fn original_slot_generation_exhaustion_refuses_before_native_exchange(){let mut original=RetainedOriginalSlot::new(7u64);original.generation=u64::MAX;let key=original.key();let mut next=Some(9);let error=original.replace(&mut next,grant(RetainedOriginalSlot::<u64>::replace_demand())).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvariantViolated);assert_eq!((original.get(),next,original.key()),(&7,Some(9),key));}

#[test]
fn original_slot_exchange_matches_all_independent_portable_outputs(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for law in corpus["cases"].as_array().unwrap(){let mut slot=RetainedOriginalSlot::new(serde_json::to_string(&law["original"]).unwrap());let mut remaining=work(slot.get().len().checked_add(serde_json::to_string(&law["replacement"]).unwrap().len()).unwrap());let old_pointer=slot.get().as_ptr();let key=slot.key();let mut next=Some(serde_json::to_string(&law["replacement"]).unwrap());let next_pointer=next.as_ref().unwrap().as_ptr();let d=RetainedOriginalSlot::<String>::replace_demand();
  for axis in [0,1,4]{let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,_=>denied.maximum_depth-=1}let(result,heap)=crate::observe_retirement_allocations(||slot.replace(&mut next,denied).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));assert_eq!(slot.get().as_ptr(),old_pointer);assert_eq!(next.as_ref().unwrap().as_ptr(),next_pointer);assert_eq!(slot.key(),key);}
  let(result,heap)=crate::observe_retirement_allocations(||slot.replace(&mut next,grant(d)).unwrap());let(previous,p)=result.unwrap();assert_eq!(heap,(0,0));assert_eq!(p.copied_bytes,d.copy_bytes);assert_eq!(p.copied_items,1);assert!(next.is_none());assert_eq!(previous.as_ptr(),old_pointer);assert_eq!(slot.get().as_ptr(),next_pointer);assert_ne!(slot.key(),key);assert_eq!(serde_json::from_str::<serde_json::Value>(slot.get()).unwrap(),law["expected"]);
  let current=slot.try_into_original().unwrap_or_else(|_|panic!("portable exchange original remains uniquely owned"));for original in [previous,current]{let mut close=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::new(original).map_err(|(e,_)|e).unwrap();while !close.terminal_is_empty(){tick(&mut remaining);let d=close.next_demand(4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||close.step(grant(d)).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}}
 }
}

static RETIRED_POINTER:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
#[derive(semio_framework_value_factory::FactoryPayloadRetirement)]
#[value(crate="semio_framework_value_factory")]
struct OriginalIssuer;
impl ArtifactOwnedValueRetirementFactory<String> for OriginalIssuer{fn retire_owned_work_demand(&self,_:&String)->Result<u64,crate::ValueError>{Ok(1)}fn retirement_birth_bytes(&self,_:&String)->usize{semio_framework_value_retirement::owned_retirement_birth_bytes::<String>()}fn retire_owned(&self,value:String,g:RetainedCloneGrant)->crate::RetainedWorkOutcome<(Box<dyn crate::ErasedSnapshotRetirement>,RetainedCloneProgress),(crate::OriginalRetirementFailure,String)>{let turn=(||{RETIRED_POINTER.store(value.as_ptr()as usize,std::sync::atomic::Ordering::Relaxed);semio_framework_value_retirement::admit_owned_retirement(value,g)})();crate::RetainedWorkOutcome{result:turn.result.map_err(|(error,value)|(error.into(),value)),work:turn.work}}}
#[test]
fn original_slot_retirement_returns_all_readers_then_uses_same_captured_payload_issuer(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for state in law["policy"]["readBirthStates"].as_array().unwrap(){let prefix=state["prefix"].as_u64().unwrap();RETIRED_POINTER.store(0,std::sync::atomic::Ordering::Relaxed);let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(OriginalIssuer);let mut slot=RetainedOriginalSlot::new("original cancelled α\0😀".repeat(8192));let mut remaining=work(slot.get().len());let pointer=slot.get().as_ptr()as usize;let key=slot.key();if state["state"]=="published"{assert_eq!(prefix,2);while slot.borrow(key).is_err(){tick(&mut remaining);let d=slot.demands(key).unwrap();let(turn,heap)=crate::observe_retirement_allocations(||slot.advance_read(key,&factory,grant(d)));let p=turn.result.unwrap().progress();assert!(turn.work<=1);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));}}else{for _ in 0..prefix{let d=slot.demands(key).unwrap();slot.advance_read(key,&factory,grant(d)).result.unwrap();}}
  let mut projection=if prefix==2{Some(slot.retain_read(key,grant(semio_framework_value_retained_clone::RetainedOwnedProjection::<String>::constructor_demand())).result.unwrap().0)}else{None};let mut owner=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::new(slot).map_err(|(e,_)|e).unwrap();
  for turn in 0..10000{if turn==5{if let Some(projection)=projection.as_mut(){while !projection.terminal_is_empty(){tick(&mut remaining);let d=projection.close_demand(4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||projection.close_step(grant(d)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}}projection=None;}
   if owner.terminal_is_empty(){break;}let d=owner.next_demand(4096).unwrap();for axis in 0..5{let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue}let(result,heap)=crate::observe_retirement_allocations(||owner.step(denied));match result{Ok(step)=>assert_eq!(step.progress(),RetainedCloneProgress::default()),Err(error)=>assert_eq!(error.retained_progress(),RetainedCloneProgress::default())}assert_eq!(heap,(0,0));}
   let(step,heap)=crate::observe_retirement_allocations(||owner.step(grant(d)).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));if projection.is_some(){assert_eq!(RETIRED_POINTER.load(std::sync::atomic::Ordering::Relaxed),0);}
  }assert!(owner.terminal_is_empty());assert!(projection.is_none());assert_eq!(RETIRED_POINTER.load(std::sync::atomic::Ordering::Relaxed),if prefix==0{0}else{pointer});let mut issuer=crate::FactoryAuthority::new(factory);while !issuer.terminal_is_empty(){tick(&mut remaining);issuer.step(grant(issuer.demands(4096).unwrap())).result.unwrap();}
 }
}

#[test]
fn original_slot_withdrawal_and_installation_preserve_exact_owners_and_resident_identity(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for row in corpus["cases"].as_array().unwrap(){for install in [false,true]{
  let mut slot=RetainedOriginalSlot::new(serde_json::to_string(&row["original"]).unwrap());let original_pointer=slot.get().as_ptr();let original_key=slot.key();let foreign=RetainedOriginalSlot::new(String::new()).key();let mut output=None;let d=RetainedOriginalSlot::<String>::transfer_demand();
  for candidate in [foreign]{let(result,heap)=crate::observe_retirement_allocations(||slot.take_original(candidate,&mut output,grant(d)));assert!(result.is_err());assert_eq!(heap,(0,0));assert!(output.is_none());}
  for axis in [0,1,4]{let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,_=>denied.maximum_depth-=1}let(result,heap)=crate::observe_retirement_allocations(||slot.take_original(original_key,&mut output,denied).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));assert_eq!(slot.get().as_ptr(),original_pointer);assert_eq!(slot.key(),original_key);assert!(output.is_none());}
  let(result,heap)=crate::observe_retirement_allocations(||slot.take_original(original_key,&mut output,grant(d)).unwrap());assert!(result.unwrap().fits(grant(d)));assert_eq!(heap,(0,0));assert_eq!(slot.is_empty(),row["vacant"].as_bool().unwrap());assert_eq!(serde_json::from_str::<serde_json::Value>(output.as_ref().unwrap()).unwrap(),row["withdrawn"]);assert_eq!(output.as_ref().unwrap().as_ptr(),original_pointer);assert_ne!(slot.key(),original_key);
  let mut replacement=Some(serde_json::to_string(&row["replacement"]).unwrap());let next_pointer=replacement.as_ref().unwrap().as_ptr();let empty_key=slot.key();let(stale,heap)=crate::observe_retirement_allocations(||slot.install_original(original_key,&mut replacement,grant(d)));assert!(stale.is_err());assert_eq!(heap,(0,0));
  if install{for axis in [0,1,4]{let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,_=>denied.maximum_depth-=1}let(result,heap)=crate::observe_retirement_allocations(||slot.install_original(empty_key,&mut replacement,denied).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));assert!(slot.is_empty());assert_eq!(slot.key(),empty_key);assert_eq!(replacement.as_ref().unwrap().as_ptr(),next_pointer);}
   let(result,heap)=crate::observe_retirement_allocations(||slot.install_original(empty_key,&mut replacement,grant(d)).unwrap());assert!(result.unwrap().fits(grant(d)));assert_eq!(heap,(0,0));assert!(replacement.is_none());assert_eq!(slot.get().as_ptr(),next_pointer);assert_eq!(serde_json::from_str::<serde_json::Value>(slot.get()).unwrap(),row["expected"]);
  }
  let mut close=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::new(slot).map_err(|(e,_)|e).unwrap();while !close.terminal_is_empty(){let selected=close.select(4096).unwrap();let d=selected.demands();let(step,heap)=crate::observe_retirement_allocations(||selected.step(grant(d)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
  for value in [output,replacement].into_iter().flatten(){let mut owner=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();while !owner.terminal_is_empty(){let selected=owner.select(4096).unwrap();let d=selected.demands();let(step,heap)=crate::observe_retirement_allocations(||selected.step(grant(d)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}}
 }}
}

#[test]
fn original_read_real_null_preserves_payload_and_direct_work_through_paid_closure(){
 use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread as refuse};
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();
 let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default());
 let mut original=RetainedOriginalSlot::new(law["text"].as_str().unwrap().to_owned());let pointer=original.get().as_ptr();let key=original.key();let d=original.demands(key).unwrap();let g=grant(d);
 let(denied,heap)=observe(||original.advance_read(key,&factory,RetainedCloneGrant{maximum_items:0,..g}));assert_eq!(denied.work,law["deniedWork"].as_u64().unwrap());assert_eq!(heap,(0,0));assert_eq!(original.get().as_ptr(),pointer);
 let((turn,attempts),heap)=observe(||refuse(||original.advance_read(key,&factory,g)));assert_eq!(attempts,1);assert_eq!(turn.work,law["nullWork"].as_u64().unwrap());assert!(turn.result.is_err());assert_eq!(heap,(0,0));assert_eq!(original.get().as_ptr(),pointer);assert!(!original.has_read());
 let mut remaining=RetainedCloneGrant{maximum_items:law["cpuStock"].as_u64().unwrap()as usize,maximum_copy_bytes:law["copyStock"].as_u64().unwrap()as usize,maximum_capacity_bytes:law["capacityStock"].as_u64().unwrap()as usize,maximum_release_bytes:law["releaseStock"].as_u64().unwrap()as usize,maximum_depth:law["maximumDepth"].as_u64().unwrap()as usize};remaining.maximum_items-=turn.work as usize;
 let(turn,heap)=observe(||original.advance_read(key,&factory,g));assert_eq!(turn.work,law["birthWork"].as_u64().unwrap());let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));remaining.maximum_items-=turn.work as usize;remaining.maximum_copy_bytes-=p.copied_bytes;remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;assert_eq!(serde_json::from_str::<serde_json::Value>(&serde_json::to_string(original.get()).unwrap()).unwrap(),law["text"]);assert_eq!(original.get().as_ptr(),pointer);
 let mut close=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::new(original).map_err(|(e,_)|e).unwrap();
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if close.terminal_is_empty(){break}let d=close.next_demand(4096).unwrap();let g=grant(d);assert!(g.maximum_items<=remaining.maximum_items&&g.maximum_copy_bytes<=remaining.maximum_copy_bytes&&g.maximum_capacity_bytes<=remaining.maximum_capacity_bytes&&g.maximum_release_bytes<=remaining.maximum_release_bytes&&g.maximum_depth<=remaining.maximum_depth);let result=close.step(g);let work=close.last_turn_work();assert!(work<=remaining.maximum_items as u64);remaining.maximum_items-=work as usize;let p=result.unwrap().progress();remaining.maximum_copy_bytes-=p.copied_bytes;remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;remaining.maximum_release_bytes-=p.released_bytes;}
 assert!(close.terminal_is_empty());let mut issuer=crate::FactoryAuthority::new(factory);
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if issuer.terminal_is_empty(){break}let g=grant(issuer.demands(4096).unwrap());let turn=issuer.step(g);assert!(turn.work<=remaining.maximum_items as u64);remaining.maximum_items-=turn.work as usize;let p=turn.result.unwrap().progress();remaining.maximum_copy_bytes-=p.copied_bytes;remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;remaining.maximum_release_bytes-=p.released_bytes;}assert!(issuer.terminal_is_empty());
}

struct PartialBank{remaining:RetainedCloneGrant,cpu:u64}
impl PartialBank{
 fn new(law:&serde_json::Value)->Self{Self{remaining:RetainedCloneGrant{maximum_items:law["itemStock"].as_u64().unwrap()as usize,maximum_copy_bytes:law["copyStock"].as_u64().unwrap()as usize,maximum_capacity_bytes:law["capacityStock"].as_u64().unwrap()as usize,maximum_release_bytes:law["releaseStock"].as_u64().unwrap()as usize,maximum_depth:law["maximumDepth"].as_u64().unwrap()as usize},cpu:law["cpuStock"].as_u64().unwrap()}}
 fn grant(&self,d:RetirementDemand)->RetainedCloneGrant{let g=grant(d);assert!(self.cpu>0&&g.maximum_items<=self.remaining.maximum_items&&g.maximum_copy_bytes<=self.remaining.maximum_copy_bytes&&g.maximum_capacity_bytes<=self.remaining.maximum_capacity_bytes&&g.maximum_release_bytes<=self.remaining.maximum_release_bytes&&g.maximum_depth<=self.remaining.maximum_depth);g}
 fn post(&mut self,turn:crate::RetainedWorkOutcome,heap:(usize,usize),g:RetainedCloneGrant){self.cpu=self.cpu.checked_sub(turn.work).unwrap();let p=match &turn.result{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.remaining.maximum_items=self.remaining.maximum_items.checked_sub(p.copied_items).unwrap();self.remaining.maximum_copy_bytes=self.remaining.maximum_copy_bytes.checked_sub(p.copied_bytes).unwrap();self.remaining.maximum_capacity_bytes=self.remaining.maximum_capacity_bytes.checked_sub(p.retained_capacity_bytes).unwrap();self.remaining.maximum_release_bytes=self.remaining.maximum_release_bytes.checked_sub(p.released_bytes).unwrap();turn.result.unwrap();}
}
static PARTIAL_RETIRED_POINTER:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
#[derive(semio_framework_value_factory::FactoryPayloadRetirement)]
#[value(crate="semio_framework_value_factory")]
struct PartialIssuer;
impl ArtifactOwnedValueRetirementFactory<String> for PartialIssuer{fn retire_owned_work_demand(&self,_:&String)->Result<u64,crate::ValueError>{Ok(1)}
 fn retirement_birth_bytes(&self,_:&String)->usize{semio_framework_value_retirement::owned_retirement_birth_bytes::<String>()}
 fn retire_owned(&self,value:String,g:RetainedCloneGrant)->crate::RetainedWorkOutcome<(Box<dyn crate::ErasedSnapshotRetirement>,RetainedCloneProgress),(crate::OriginalRetirementFailure,String)>{let turn=(||{PARTIAL_RETIRED_POINTER.store(value.as_ptr()as usize,std::sync::atomic::Ordering::Relaxed);semio_framework_value_retirement::admit_owned_retirement(value,g)})();crate::RetainedWorkOutcome{result:turn.result.map_err(|(error,value)|(error.into(),value)),work:turn.work}}
}
#[test]
fn every_partial_source_admission_returns_the_same_slot_payload_through_its_captured_issuer(){
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("actual.schema.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}
 for cut in law["sourceAdmissionCuts"].as_array().unwrap(){PARTIAL_RETIRED_POINTER.store(0,std::sync::atomic::Ordering::Relaxed);let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(PartialIssuer);let mut slot=RetainedOriginalSlot::new(law["text"].as_str().unwrap().to_owned());let pointer=slot.get().as_ptr();let key=slot.key();let mut bank=PartialBank::new(&law);
  for _ in 0..law["sourceAdmissionBaseControls"].as_u64().unwrap()+cut.as_u64().unwrap(){let g=bank.grant(slot.demands(key).unwrap());let(turn,heap)=crate::observe_retirement_allocations(||slot.advance_read(key,&factory,g));bank.post(turn,heap,g);assert_eq!(slot.get().as_ptr(),pointer);assert_eq!(slot.key(),key);}assert!(slot.has_read());assert!(slot.borrow(key).is_err());assert_eq!(serde_json::to_value(slot.get()).unwrap(),law["text"]);
  let mut owner=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::retain(slot);
  for _ in 0..law["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break}let g=bank.grant(owner.next_demand(4096).unwrap());let(result,heap)=crate::observe_retirement_allocations(||owner.step(g));bank.post(crate::RetainedWorkOutcome{result,work:owner.last_turn_work()},heap,g);}assert!(owner.terminal_is_empty());assert_eq!(PARTIAL_RETIRED_POINTER.load(std::sync::atomic::Ordering::Relaxed),pointer as usize);
  let mut issuer=crate::FactoryAuthority::new(factory);for _ in 0..law["maximumTurns"].as_u64().unwrap(){if issuer.terminal_is_empty(){break}let g=bank.grant(issuer.demands(4096).unwrap());let(turn,heap)=crate::observe_retirement_allocations(||issuer.step(g));bank.post(turn,heap,g);}assert!(issuer.terminal_is_empty());assert_eq!(crate::observe_retirement_allocations(||drop((owner,issuer))).1,(0,0));
 }
}

#[test]
fn original_read_return_start_is_a_distinct_denied_or_paid_zero_heap_control(){
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("actual.schema.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}let mut bank=PartialBank::new(&law);let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default());let mut slot=RetainedOriginalSlot::new(law["text"].as_str().unwrap().to_owned());let pointer=slot.get().as_ptr();let key=slot.key();let g=bank.grant(slot.demands(key).unwrap());let(turn,heap)=crate::observe_retirement_allocations(||slot.advance_read(key,&factory,g));bank.post(turn,heap,g);assert!(slot.has_read());
 let expected=RetirementDemand{copy_bytes:law["returnStart"]["copyBytes"].as_u64().unwrap()as usize,capacity_bytes:law["returnStart"]["capacityBytes"].as_u64().unwrap()as usize,release_bytes:law["returnStart"]["releaseBytes"].as_u64().unwrap()as usize,depth:law["returnStart"]["depth"].as_u64().unwrap()as usize};assert_eq!(slot.return_demands(key,4096).unwrap(),expected);let g=bank.grant(expected);let mut returned=None;
 for denied in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(turn,heap)=crate::observe_retirement_allocations(||slot.return_read(key,&mut returned,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));assert!(slot.has_read());assert!(returned.is_none());assert_eq!(slot.get().as_ptr(),pointer);assert_eq!(slot.return_demands(key,4096).unwrap(),expected);}
 let(turn,heap)=crate::observe_retirement_allocations(||slot.return_read(key,&mut returned,g));assert_eq!(turn.work,law["returnStart"]["work"].as_u64().unwrap());assert_eq!(heap,(0,0));let p=turn.result.as_ref().unwrap().progress();assert_eq!(p,RetainedCloneProgress{copied_items:1,..Default::default()});bank.post(turn,heap,g);assert!(slot.has_read());assert!(returned.is_none());assert_eq!(slot.get().as_ptr(),pointer);assert!(slot.return_demands(key,4096).unwrap().release_bytes>0);
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if !slot.has_read(){break}let g=bank.grant(slot.return_demands(key,4096).unwrap());let(turn,heap)=crate::observe_retirement_allocations(||slot.return_read(key,&mut returned,g));bank.post(turn,heap,g);}assert!(!slot.has_read());assert_eq!(slot.get().as_ptr(),pointer);assert_eq!(serde_json::to_value(slot.get()).unwrap(),law["text"]);let mut returned_issuer=crate::FactoryAuthority::new(returned.take().unwrap());let mut original_issuer=crate::FactoryAuthority::new(factory);
 let(turn,heap)=crate::observe_retirement_allocations(||slot.return_read(key,&mut returned,Default::default()));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));
 let mut owner=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::retain(slot);for _ in 0..law["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break}let g=bank.grant(owner.next_demand(4096).unwrap());let(result,heap)=crate::observe_retirement_allocations(||owner.step(g));bank.post(crate::RetainedWorkOutcome{result,work:owner.last_turn_work()},heap,g);}assert!(owner.terminal_is_empty());for issuer in [&mut returned_issuer,&mut original_issuer]{for _ in 0..law["maximumTurns"].as_u64().unwrap(){if issuer.terminal_is_empty(){break}let g=bank.grant(issuer.demands(4096).unwrap());let(turn,heap)=crate::observe_retirement_allocations(||issuer.step(g));bank.post(turn,heap,g);}assert!(issuer.terminal_is_empty());}assert_eq!(crate::observe_retirement_allocations(||drop((owner,returned_issuer,original_issuer))).1,(0,0));
}
